"""One video element; switch clips without simultaneous playback or autoplay."""
import html,json,pathlib
R=pathlib.Path(__file__).resolve().parent
manifest=json.loads((R/'clips.json').read_text());review=json.loads((R/'review.json').read_text())
data=json.dumps({'clips':manifest['clips'],'inventory':review['heard_inventory']},ensure_ascii=False).replace('</','<\\/')
page=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Neon Warden: Argon creative review</title>
<style>
:root{color-scheme:dark;font:16px/1.5 system-ui;background:#0b111a;color:#e7eff8}body{max-width:1000px;margin:auto;padding:22px}h1{font-size:1.7rem;line-height:1.2}h2{font-size:1.15rem}p{max-width:80ch}.muted{color:#a9b8c9}nav{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}button{font:inherit;padding:7px 11px;color:inherit;background:#182536;border:1px solid #38516d;border-radius:5px;cursor:pointer}button[aria-pressed=true]{outline:2px solid #7de9ec}video{width:100%;max-height:563px;background:#000}a{color:#91e2e9}.box{padding:14px;background:#141f2d;margin-top:15px;border-radius:6px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;margin:0}summary{cursor:pointer}#spoiler{color:#f5bd81;font-weight:bold}#inventory{font-size:.92rem}ul{padding-left:22px}@media(max-width:600px){body{padding:14px}h1{font-size:1.35rem}}
</style>
<h1>Argon creative review: protect the voice, concentrate the craft</h1>
<p class="muted">Isolated build <code>ad320434</code>, Captain/cand1 selection overlays. Seven continuous AV excerpts; one clip at a time. Desktop capture, not hands-on testing. Research only, no game changes.</p>
<p><a href="README.md">Selective response and source corroboration</a> · <a href="DIRECTOR.md">Unedited director memo</a> · <a href="response.json">Raw response</a> · <a href="provenance.json">Exact inputs</a> · <a href="validation.json">Validation</a></p>
<nav aria-label="Review clips" id="clips"></nav><h2 id="title"></h2><p id="spoiler" hidden>SPOILERS: lethal ending excerpt. Click Play only if you want to see it.</p>
<video id="player" controls preload="metadata" playsinline></video><p class="muted" id="context"></p>
<section class="box"><h2>Transcript-first evidence, Argon's own account</h2><div id="inventory"></div><p class="muted">Approximate observer times, not frame-accurate annotations. Audio source starts and event logs corroborate some claims; they do not prove every interpretation.</p></section>
<section class="box"><h2>Selective production response</h2><ul><li>Protect the corporate AI / Warden / briefing contrast, scan/disarm verb and clear lane.</li><li>Audit first-time VO event arbitration; don't rebuild an existing scheduler blindly.</li><li>Test subtitle emphasis without the crowding caused by scaled word spans.</li><li>Make one pod-break cue causally coherent before adding generic spectacle.</li><li>Reject the supposed repeated recorder defect: D and E are independent fresh runs.</li></ul></section>
<details class="box"><summary>Coverage, capture caveats and spend</summary><p>Actual game audio via qa/av.ts. No page exceptions. All excerpts have non-silent stereo audio, -19.5 to -16.8 LUFS; no clipping. Clip D has a VO coverage failure, not an all-green QA result. Combat captures run about 52 ticks/wall-second versus nominal 60, with no speed multiplier; tutorial about 59.2. D/E are separate scenes, not uninterrupted progression. B's hangar redesign is pending. G is a QA scene entry, not an earned run.</p><p>No supplied comparator media: Returnal, Control, Dead Space and Wipeout are named conceptual references only. No judgment of mobile usability, full narrative or hands-on feel.</p><p>One request to verified google/gemini-4-argon, returned provider Google, mandatory ZDR and data_collection deny. Cost US $0.117510. Raw malformed JSON string was recovered locally without another call.</p></details>
<script>const DATA=__DATA__;const player=document.querySelector('#player'),nav=document.querySelector('#clips');
function node(tag,text){const e=document.createElement(tag);e.textContent=text;return e;}
function choose(id){const c=DATA.clips.find(x=>x.id===id),inv=DATA.inventory.find(x=>x.clip===id);player.pause();player.src=c.path;player.poster='out/'+id+'/frame.jpg';player.load();document.querySelector('#title').textContent=c.id+': '+c.title;document.querySelector('#spoiler').hidden=id!=='G';document.querySelector('#context').textContent=c.duration_s+' s, continuous excerpt. '+(c.active_ticks_per_wall_second_median?'Measured active tick rate: '+c.active_ticks_per_wall_second_median+'/wall-second. ':'')+'No simulation speed multiplier.';for(const b of nav.children)b.setAttribute('aria-pressed',String(b.dataset.id===id));const box=document.querySelector('#inventory');box.replaceChildren();const lines=inv.vo_transcript??[];if(!lines.length)box.append(node('p','No voice transcript reported.'));for(const line of lines)box.append(node('p',line.time_range+' | '+line.speaker+': '+line.verbatim_heard));box.append(node('p','Music heard: '+inv.music_character),node('p','SFX heard: '+inv.sfx_character),node('p','Observer uncertainty: '+inv.uncertainty_and_notes));const d=node('details','');d.append(node('summary','Text read, not heard'),node('pre',(inv.ui_or_subtitle_text_only_not_heard??[]).join('\n')));box.append(d);}
for(const c of DATA.clips){const b=node('button',c.id+(c.id==='G'?' · Spoilers':''));b.dataset.id=c.id;b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>choose(c.id));nav.append(b);}choose('A');</script></html>'''
